node -e "
const l=require('./package-lock.json');
const bad=[];
for(const [k,v] of Object.entries(l.packages)){
  const p=v.peerDependencies||{};
  for(const dep of ['react','react-dom']){
    if(p[dep] && !/\^18|>= ?18|>=16|>= 16|>=17|\*/.test(p[dep]) && !p[dep].includes('18')){
      bad.push([k,v.version,dep,p[dep]]);
    }
  }
}
console.log(bad.map(x=>x.join(' | ')).join('\n'));
console.log('count',bad.length);
"

node -e "
const https=require('https');
const l=require('./package-lock.json');
const names=['axios','react','@mui/styles','lodash','typescript'];
function get(u){return new Promise((res,rej)=>{https.get(u,r=>{let d='';r.on('data',c=>d+=c);r.on('end',()=>res(JSON.parse(d)))}).on('error',rej)})}
(async()=>{
 for(const n of names){
   const k='node_modules/'+n;
   if(!l.packages[k]) {console.log(n,'not in lock');continue;}
   const v=l.packages[k].version;
   try{
     const m=await get('https://registry.npmjs.org/'+n.replace('/','%2f')+'/'+v);
     console.log(n, v, 'lock=',l.packages[k].integrity, 'registry=',m.dist.integrity, l.packages[k].integrity===m.dist.integrity?'MATCH':'DIFF');
   }catch(e){console.log(n,v,'ERR',e.message)}
 }
})();
"

